-- Review template. The actual existing profile UUID is resolved privately; no fictitious user is created.
begin isolation level repeatable read read only;
set local transaction_read_only=on;set local statement_timeout='8s';set local lock_timeout='1s';set local search_path=pg_catalog;
set local request.jwt.claims='{"sub":"00000000-0000-0000-0000-000000000000","role":"authenticated","aal":"aal2"}';
set local role authenticated;
select jsonb_build_object('observed_at',transaction_timestamp(),'database',current_database(),'effective_database_role',current_user,'application_role',public.current_app_role(),
 'read_only',current_setting('transaction_read_only'),'subject_present',auth.uid() is not null,'mfa_context_replayed',true,
 'reads',(select jsonb_agg(to_jsonb(x) order by x.relation) from(select 'case_events' relation,count(*)::integer sample_visible from(select "archive_message_id","area","evidence_type","id","kind","occurred_at","opportunity_id","process_id","submission_id" from public."case_events" limit 1) bounded union all select 'documents' relation,count(*)::integer sample_visible from(select "content_hash","created_at","id","kind","opportunity_id","required","status","storage_path" from public."documents" limit 1) bounded union all select 'financing_processes' relation,count(*)::integer sample_visible from(select "actual_funded_amount","classification","funded_lender_id","id","is_unclassified_archive","opportunity_id","sequence_number","started_at","state" from public."financing_processes" limit 1) bounded union all select 'lead_workspace' relation,count(*)::integer sample_visible from(select "company","contact","contact_id","created_at","email","id","opportunity_id","seller_id","suppressed","verification" from public."lead_workspace" limit 1) bounded union all select 'lenders' relation,count(*)::integer sample_visible from(select "email","id","name" from public."lenders" limit 1) bounded union all select 'mail_accounts' relation,count(*)::integer sample_visible from(select "email","id","owner_id" from public."mail_accounts" limit 1) bounded union all select 'mail_archive_visible' relation,count(*)::integer sample_visible from(select "account_id","direction","gmail_thread_id","id","nature","participants","reply_intent","sent_at","subject" from public."mail_archive_visible" limit 1) bounded union all select 'mail_conversations_visible' relation,count(*)::integer sample_visible from(select "account_id","area","id","needs_attention","opportunity_id","process_id","subject","submission_id","updated_at" from public."mail_conversations_visible" limit 1) bounded union all select 'messages' relation,count(*)::integer sample_visible from(select "archive_message_id","area","body","conversation_id","direction","id","nature","reply_intent","sender","sent_at","status" from public."messages" limit 1) bounded union all select 'offers' relation,count(*)::integer sample_visible from(select "amount","cost","created_at","expires_at","fees","frequency","id","opportunity_id","product","status","submission_id","term" from public."offers" limit 1) bounded union all select 'opportunity_workspace' relation,count(*)::integer sample_visible from(select "amount","application_complete","application_signed","closer_id","company","contact","created_at","email","funded_amount","funded_at","funded_lender_id","handed_off_at","id","industry","next_action","next_action_at","phone","seller_id","stage","updated_at" from public."opportunity_workspace" limit 1) bounded union all select 'pipeline_mail_reviews' relation,count(*)::integer sample_visible from(select "id","message_id","opportunity_id","result","status" from public."pipeline_mail_reviews" limit 1) bounded union all select 'profiles' relation,count(*)::integer sample_visible from(select "active","email","id","name","role" from public."profiles" limit 1) bounded union all select 'submissions' relation,count(*)::integer sample_visible from(select "closer_id","id","lender_id","next_action","next_action_at","opportunity_id","process_id","status","submitted_at" from public."submissions" limit 1) bounded union all select 'tasks' relation,count(*)::integer sample_visible from(select "area","due_at","id","opportunity_id","owner_id","status","title" from public."tasks" limit 1) bounded)x)) master_rls;
reset role;rollback;
